function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function buildPrd(f){
  f=f||{};
  var name=String(f.name||'未命名功能').trim()||'未命名功能';
  var users=String(f.users||'').trim()||'（待补充）';
  var problem=String(f.problem||'').trim()||'（待补充）';
  var goals=String(f.goals||'').trim()||'（待补充）';
  var features=splitLines(f.features);
  var nonGoals=String(f.nonGoals||'').trim()||'（待补充）';
  var metrics=String(f.metrics||'').trim()||'';
  var milestones=splitLines(f.milestones);
  var lines=[];
  lines.push('# 产品需求文档（PRD）：'+name);
  lines.push('');
  lines.push('## 背景与问题'); lines.push(problem); lines.push('');
  lines.push('## 目标用户'); lines.push(users); lines.push('');
  lines.push('## 目标与成功指标'); lines.push(goals); lines.push('');
  if(metrics){ lines.push('成功度量：'+metrics); lines.push(''); }
  lines.push('## 功能需求');
  if(features.length){ features.forEach(function(fe,i){ lines.push((i+1)+'. '+fe); }); }
  else lines.push('（待补充）');
  lines.push('');
  lines.push('## 非目标（范围外）'); lines.push(nonGoals); lines.push('');
  if(milestones.length){ lines.push('## 里程碑'); milestones.forEach(function(ms){ lines.push('- '+ms); }); lines.push(''); }
  return {title:name, featureCount:features.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildPrd:buildPrd};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PrdForgePure = EXPORTS; }
